package unstable

func tree(b *Builder, n Node, children ...Reference) Reference {
	ref := b.Push(n)
	var prev Reference
	for i, child := range children {
		if i == 0 {
			b.AttachChild(ref, child)
		} else {
			b.Chain(prev, child)
		}
		prev = child
	}
	return ref
}

func withComment(b *Builder, ref Reference, comments ...[]byte) Reference {
	current := ref
	for _, data := range comments {
		c := b.Push(Node{Kind: Comment, Data: data})
		b.AttachComment(current, c)
		current = c
	}
	return ref
}

